import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Первый сервер","description":"","frontmatter":{"pageId":"admins/getting-started","contentRevision":1},"headers":[],"relativePath":"ru/admins/getting-started.md","filePath":"ru/admins/getting-started.md"}'),r={name:"ru/admins/getting-started.md"};function n(s,a,o,d,h,c){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="первыи-сервер" tabindex="-1">Первый сервер <a class="header-anchor" href="#первыи-сервер" aria-label="Permalink to &quot;Первый сервер&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><ol><li>Выбери хост с постоянным диском и доступным TCP 25560. Подготовь закрытый каталог данных и резервное копирование.</li><li>Установи релиз сервера либо используй контейнер. Зафиксируй версию образа, не полагайся на latest для воспроизводимого восстановления.</li><li>Настрой TLS, личный способ входа, первоначального администратора и отдельный сильный Admin:ApiToken. Парольный вход по умолчанию выключен.</li><li>Запусти сервер, проверь /health, затем вход в панель /admin/ по HTTPS и игровой вход.</li><li>Создай общий мир административным клиентом, задай набор модов и пригласи тестового игрока.</li><li>Сделай резервную копию и восстанови её в отдельном тестовом каталоге до публичного открытия.</li></ol><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Открытый /health не доказывает работоспособность авторизации и сохранений. Не выставляй /metrics и админ-панель в интернет без сетевой политики. Создание/пересоздание мира — не безобидная проверка.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./hosting">Размещение и запуск</a></li><li><a href="./security-auth">TLS, вход и права</a></li><li><a href="./backup-recovery">Резервные копии и восстановление</a></li></ul>',8)])])}const _=e(r,[["render",n]]);export{u as __pageData,_ as default};
